/**
 * R5g — TypeScript types for the Tracker SMS rules document (schema v2).
 *
 * The document is GENERATED by scripts/rules/build_rules.js (bundled copy:
 * rules.json next to this file). Field reference: RULES.md. Every regex,
 * id and sample in it is original (synthetic bodies).
 */

export type RuleSmsType = 'transaction' | 'statement' | 'notice' | 'balance' | 'event' | 'ignore';

export type RuleAccountType =
  | 'bank'
  | 'credit_card'
  | 'debit_card'
  | 'wallet'
  | 'prepaid'
  | 'loan'
  | 'pay_later'
  | 'utility'
  | 'insurance';

export type RuleMoneyKind =
  | 'spend'
  | 'income'
  | 'refund'
  | 'transfer'
  | 'card_payment'
  | 'atm'
  | 'wallet_load'
  | 'emi'
  | 'interest';

export type RuleMatchType = 'exact' | 'delta' | 'value' | 'none' | 'same_or_alias' | 'exact_if_present';

export type RuleScope = 'financial_fallback' | 'any_sender';

export type RuleRefType = 'upi' | 'imps' | 'neft' | 'rtgs';

export type RuleDirection = 'debit' | 'credit';

export interface RulePreprocessor {
  find: string;
  replace: string;
  flags?: string;
}

/** `{group_id}` (first non-empty group wins) or `{value}` (a constant). */
export interface RuleGroupRef {
  group_id?: number | number[];
  value?: string;
}

export interface RulePanField extends RuleGroupRef {
  /** 3 = a 3-digit mask is accepted (→ lastDigits). */
  min_digits?: number;
}

export interface RulePosField extends RuleGroupRef {
  /** Merchant 'Unknown' is acceptable for confidence (no penalty). */
  set_no_pos?: boolean;
}

export interface RuleCurrencyField extends RuleGroupRef {
  default?: string;
  aliases?: Record<string, string>;
}

export interface RuleDateFormat {
  /** Tokens yyyy yy MMMM MMM MM dd d HH hh mm ss a, 'quoted' literals, or 'immediate'. */
  format: string;
  use_sms_time?: boolean;
}

export interface RuleDateField {
  group_id?: number | number[];
  formats?: RuleDateFormat[];
  use_sms_time?: boolean;
}

export interface RuleRefTypeRule {
  value: string;
  ref_type: RuleRefType;
}

export interface RuleRefField extends RuleGroupRef {
  type_rule?: { rules: RuleRefTypeRule[] };
}

export interface RuleTxnTypeRuleEntry {
  value: string;
  txn_type?: string;
  pos_override?: string;
  set_no_pos?: boolean;
  acc_type_override?: RuleAccountType;
  money_kind_override?: RuleMoneyKind;
}

export interface RuleTxnTypeRule {
  group_id: number | number[];
  rules: RuleTxnTypeRuleEntry[];
}

export interface RulePosTypeRuleEntry {
  value: string;
  category: string;
  income_flag_override?: boolean;
}

export interface RulePosTypeRules {
  group_id: number | number[];
  rules: RulePosTypeRuleEntry[];
}

export interface RuleChainSelector {
  parent_field: string;
  child_field?: string;
  match_type: RuleMatchType;
  match_value?: string | number;
}

export interface RuleChainOverride {
  incomplete?: boolean;
  deleted?: boolean;
  link?: 'refund' | 'transfer_twin' | 'duplicate';
}

export interface RuleChainingRule {
  parent_selection: RuleChainSelector[];
  parent_match?: { parent_override?: RuleChainOverride; child_override?: RuleChainOverride };
  parent_nomatch?: { child_override?: RuleChainOverride };
}

export interface RuleDataFields {
  transaction_type?: RuleDirection;
  money_kind?: RuleMoneyKind;
  statement_type?: string;
  notice_type?: string;
  ignore_reason?: string;
  amount?: RuleGroupRef;
  pan?: RulePanField;
  counterparty_pan?: RulePanField;
  counterparty_name?: RuleGroupRef;
  pos?: RulePosField;
  note?: RuleGroupRef;
  date?: RuleDateField;
  account_balance?: RuleGroupRef;
  outstanding_balance?: RuleGroupRef;
  available_limit?: RuleGroupRef;
  min_due_amount?: RuleGroupRef;
  currency?: RuleCurrencyField;
  network_reference_id?: RuleRefField;
  transaction_type_rule?: RuleTxnTypeRule;
  pos_type_rules?: RulePosTypeRules;
  recurring_hint?: boolean;
  category_hint?: string;
  enable_chaining?: boolean;
  chaining_rule?: RuleChainingRule;
  incomplete?: boolean;
  deleted?: boolean;
  event_type?: string;
  pnr?: RuleGroupRef;
  event_location?: RuleGroupRef;
  event_info?: RuleGroupRef;
  event_reminder_span?: RuleGroupRef;
  name?: RuleGroupRef;
}

export type RuleExpect = Record<string, string | boolean>;

export interface RuleSample {
  body: string;
  expect?: RuleExpect;
  expect_records?: RuleExpect[];
}

export interface RulePattern {
  pattern_UID: string;
  sort_UID: number;
  sms_type: RuleSmsType;
  account_type: RuleAccountType;
  regex: string;
  flags?: string;
  data_fields: RuleDataFields;
  samples?: RuleSample[];
  reparse?: boolean;
  obsolete?: boolean;
  /** Epoch ms: an obsolete pattern is skipped for SMS dated after this. */
  obsolete_after?: number;
  preprocessor?: RulePreprocessor[];
  account_name_override?: string;
  set_account_as_expense?: boolean;
  create_txn?: boolean;
  show_notification?: boolean;
  _doc?: string;
}

export type RuleContactType = 'missed_call' | 'sms' | 'call';

export interface RuleGetBalance {
  account_type: RuleAccountType;
  contact_info: Array<{ type: RuleContactType; numbers: string[]; verified: boolean }>;
}

export interface RuleMiscInformation {
  get_balance?: RuleGetBalance[];
}

export interface RuleIssuer {
  name: string;
  full_name: string;
  institution_kind: string;
  senders: string[];
  sender_regexes?: string[];
  sender_status?: string;
  scope?: RuleScope;
  institution_from_body?: boolean;
  preprocessor?: RulePreprocessor[];
  misc_information?: RuleMiscInformation;
  set_account_as_expense?: boolean;
  account_name_override?: string;
  /**
   * N1 (owner 2026-11-10): true = this issuer's templates were confirmed on
   * a tester's masked "Share pattern" — they win outright over the reader.
   * Default false (none set yet).
   */
  format_verified?: boolean;
  _doc?: string | string[];
  patterns: RulePattern[];
}

export interface RulesDocument {
  _doc?: string | string[];
  schema_version: 2;
  version: number;
  min_app_version: string;
  format_status?: string;
  blacklist_regex?: string;
  rules: RuleIssuer[];
}
